input.command:
cd /workspace; cat > /tmp/diff.tmpl <<'EOF'
{{- $paths := coll.Slice "" "/" "//" "///" "." ".." "a" "/a" "a/b" "a//b" "/a/b/" "./a" "../a" "/../a" "a/./b" "a/b/../c" "foo.tar.gz" ".bashrc" "a\\b" "C:\\foo\\bar" "C:/foo/bar" "\\\\host\\share\\x" "//host/share/x" "/a/b/c/../../.." "日本語/ファイル.txt" " /a/ b " "a b/c d.e f" -}}
{{- range $p := $paths -}}
{{ printf "%q" $p }}|Base p=[{{ path.Base $p }}] f=[{{ filepath.Base $p }}]|Dir p=[{{ path.Dir $p }}] f=[{{ filepath.Dir $p }}]|Clean p=[{{ path.Clean $p }}] f=[{{ filepath.Clean $p }}]|Ext p=[{{ path.Ext $p }}] f=[{{ filepath.Ext $p }}]|IsAbs p=[{{ path.IsAbs $p }}] f=[{{ filepath.IsAbs $p }}]|Split p={{ printf "%#v" (path.Split $p) }} f={{ printf "%#v" (filepath.Split $p) }}|ToSlash=[{{ filepath.ToSlash $p }}]|FromSlash=[{{ filepath.FromSlash $p }}]|Vol=[{{ filepath.VolumeName $p }}]
{{ end -}}
EOF
./executable -f /tmp/diff.tmpl
